 use verus_state_machines_macros::tokenized_state_machine;


 verus! {

 pub struct Request {
     pub rid: int,
     pub req: int,
 }

 pub struct Response {
     pub rid: int,
     pub resp: int,
 }

 #[is_variant]
 pub enum Client {
