 tokenized_state_machine! {
     FlatCombiner {
         fields {
             #[sharding(constant)]
             pub num_clients: nat,

             #[sharding(imap)]
             pub clients: IMap<nat, Client>,

             #[sharding(imap)]
             pub slots: IMap<nat, bool>,

