             pub combiner: Combiner,

             #[sharding(storage_imap)]
             pub requests: IMap<nat, Request>,

             #[sharding(storage_imap)]
             pub responses: IMap<nat, Response>,
         }

         pub open spec fn valid_idx(self, i: nat) -> bool {
